def bucket_for(tile_mean: np.ndarray) -> int:
    """Return 0-indexed bucket for the given tile_mean frame (nearest centroid)."""
    flat = tile_mean.flatten().astype(np.float32)
    dists = np.sum((CENTROIDS - flat) ** 2, axis=1)
    return int(np.argmin(dists))
